# Summaries of the Ohau Channel at SH33 (FL230406, the lake outlet) lab data (target ohau_wq_data): inventory, time series, seasonality,
# trends (seasonal Mann-Kendall and Sen slope), before and after alum, nutrient ratios, and comparison with the lake (sites 2 and 5, top 5 m) and the joint ensemble (j50x).
# Outputs: website/data/ohau/*.csv and website/images/ohau/*.png
suppressMessages({library(dplyr); library(tidyr); library(ggplot2); library(readr); library(lubridate)})
out <- "website/images/ohau"; dat <- "website/data/ohau"; dir.create(out, recursive = TRUE, showWarnings = FALSE); dir.create(dat, recursive = TRUE, showWarnings = FALSE)
D0 <- as.Date("2006-06-15"); D1 <- as.Date("2010-01-14"); set.seed(7)
MP <- 30.974 / 1000; MN <- 14.007 / 1000; DOPR <- 0.15 * 30.974 / 1000; DONR <- 9 * 14.0067 / 1000; TAG <- "j50x"
vorder <- c("TP", "DRP", "TN", "NH4-N", "NNN", "TSS", "Water Temp"); vlab <- c(TP = "Total P (g/m3)", DRP = "DRP (g/m3)", TN = "Total N (g/m3)", `NH4-N` = "NH4-N (g/m3)", NNN = "Nitrate+nitrite N (g/m3)", TSS = "TSS (g/m3)", `Water Temp` = "Water temperature (C)")
o <- targets::tar_read(ohau_wq_data) |> transmute(Date = as.Date(Timestamp), ym = floor_date(Date, "month"), yr = year(Date), mo = month(Date), variable, value, legacy = grepl("Legacy", qualifiers), grade_code) |> mutate(variable = factor(variable, vorder))
# ---- inventory ----
inv <- o |> group_by(variable) |> summarise(n = n(), first = min(Date), last = max(Date), n_2005_on = sum(Date >= "2005-01-01"), min = min(value), median = median(value), mean = mean(value), p95 = quantile(value, .95), max = max(value), n_le_zero = sum(value <= 0), n_at_min_value = sum(value == min(value[value > 0])), .groups = "drop")
write_csv(inv |> mutate(across(where(is.numeric), \(x) signif(x, 3))), file.path(dat, "ohau_inventory.csv")); print(as.data.frame(inv), row.names = FALSE)
# ---- time series ----
ann <- o |> group_by(variable, yr) |> filter(n() >= 6) |> summarise(med = median(value), .groups = "drop") |> mutate(Date = as.Date(paste0(yr, "-07-01")))
o$lab <- vlab[as.character(o$variable)]; ann$lab <- vlab[as.character(ann$variable)]; o$lab <- factor(o$lab, vlab); ann$lab <- factor(ann$lab, vlab)
ggsave(file.path(out, "ohau_timeseries.png"), ggplot(o, aes(Date, value)) + geom_vline(xintercept = c(D0, D1), linetype = 2, colour = "grey50") + geom_point(aes(colour = legacy), size = 0.7, alpha = 0.55) + geom_line(data = ann, aes(Date, med), colour = "black", linewidth = 0.6) +
  facet_wrap(~lab, ncol = 1, scales = "free_y") + scale_colour_manual(values = c(`TRUE` = "grey55", `FALSE` = "steelblue4"), labels = c(`TRUE` = "Legacy data", `FALSE` = "Routine"), name = NULL) + labs(x = NULL, y = NULL, subtitle = "Black line: annual median (years with at least 6 samples). Dashed lines: dosing starts (Utuhina 2006-06-15, Puarenga 2010-01-14).") +
  theme_minimal(base_size = 10) + theme(legend.position = "bottom", plot.subtitle = element_text(size = 8)), width = 10, height = 14, dpi = 130, bg = "white")
# ---- seasonality (2005 onwards) ----
ggsave(file.path(out, "ohau_seasonal.png"), ggplot(o |> filter(Date >= "2005-01-01"), aes(factor(mo, 1:12, month.abb), value)) + geom_boxplot(fill = "steelblue", alpha = 0.4, outlier.size = 0.5, linewidth = 0.3) + facet_wrap(~lab, ncol = 2, scales = "free_y") + labs(x = NULL, y = NULL, subtitle = "Monthly distributions, 2005 to 2026 (boxes: quartiles; line: median).") + theme_minimal(base_size = 9) + theme(plot.subtitle = element_text(size = 8)), width = 10, height = 9, dpi = 130, bg = "white")
sea <- o |> filter(Date >= "2005-01-01") |> group_by(variable, mo) |> summarise(med = median(value), .groups = "drop") |> group_by(variable) |> summarise(peak_month = month.abb[mo[which.max(med)]], peak = max(med), low_month = month.abb[mo[which.min(med)]], low = min(med), ratio_peak_low = max(med) / min(med[med > 0] ), .groups = "drop"); write_csv(sea |> mutate(across(where(is.numeric), \(x) signif(x, 3))), file.path(dat, "ohau_seasonality.csv")); print(as.data.frame(sea), row.names = FALSE)
# ---- trends: seasonal Mann-Kendall and seasonal Sen slope (per year) ----
smk <- function(d) { g <- split(d, d$mo); S <- 0; V <- 0; sl <- c(); for (x in g) { x <- x[order(x$Date), ]; n <- nrow(x); if (n < 3) next; tt <- as.numeric(x$Date) / 365.25; ii <- combn(n, 2); s <- sign(x$value[ii[2, ]] - x$value[ii[1, ]]); S <- S + sum(s); tb <- table(x$value); V <- V + (n * (n - 1) * (2 * n + 5) - sum(tb * (tb - 1) * (2 * tb + 5))) / 18
    sl <- c(sl, (x$value[ii[2, ]] - x$value[ii[1, ]]) / (tt[ii[2, ]] - tt[ii[1, ]])) }; z <- if (S > 0) (S - 1) / sqrt(V) else if (S < 0) (S + 1) / sqrt(V) else 0; tibble(n = nrow(d), z = z, p = 2 * pnorm(-abs(z)), slope = median(sl[is.finite(sl)]), start_med = median(d$value[d$yr <= min(d$yr) + 2]), end_med = median(d$value[d$yr >= max(d$yr) - 2])) }
tr <- bind_rows(lapply(list(`2000 to 2026` = 2000, `2011 to 2026` = 2011), \(y0) o |> filter(yr >= y0) |> group_by(variable) |> filter(n() >= 40) |> group_modify(~smk(.x)) |> ungroup()), .id = "period") |> mutate(pct_per_yr = 100 * slope / median(c(start_med, end_med)))
trm <- bind_rows(lapply(split(tr, tr$period), \(tt) tt |> mutate(med_all = sapply(as.character(variable), \(v) median(o$value[o$variable == v & o$yr >= ifelse(tt$period[1] == "2000 to 2026", 2000, 2011)]))) |> mutate(pct_per_yr = 100 * slope / med_all)))
write_csv(trm |> select(-med_all) |> mutate(across(where(is.numeric), \(x) signif(x, 3))), file.path(dat, "ohau_trends.csv")); cat("\nTrends:\n"); print(as.data.frame(trm |> mutate(across(where(is.numeric), \(x) round(x, 4)))), row.names = FALSE)
# ---- before / after dosing ----
per <- \(d) cut(d, as.Date(c("1990-01-01", "2006-06-15", "2010-01-14", "2027-01-01")), c("Before dosing (to mid-2006)", "Utuhina only (2006 to 2010)", "Both streams (2010 on)"), right = FALSE)
pp <- o |> mutate(period = per(Date)) |> filter(!is.na(period), !(variable == "TN" & Date < "2009-01-01"))
pt <- pp |> group_by(variable, period) |> summarise(n = n(), median = median(value), q25 = quantile(value, .25), q75 = quantile(value, .75), .groups = "drop")
bt <- pp |> filter(period %in% levels(pp$period)[c(1, 3)]) |> group_by(variable) |> filter(n_distinct(period) == 2) |> group_modify(\(d, k) { a <- d$value[d$period == levels(pp$period)[1]]; b <- d$value[d$period == levels(pp$period)[3]]; bs <- replicate(2000, 100 * (median(sample(b, replace = TRUE)) / median(sample(a, replace = TRUE)) - 1)); tibble(change_pct = 100 * (median(b) / median(a) - 1), lo = quantile(bs, .05), hi = quantile(bs, .95), wilcox_p = suppressWarnings(wilcox.test(a, b)$p.value)) }) |> ungroup()
write_csv(pt |> mutate(across(where(is.numeric), \(x) signif(x, 3))), file.path(dat, "ohau_by_period.csv")); write_csv(bt |> mutate(across(where(is.numeric), \(x) signif(x, 3))), file.path(dat, "ohau_change_after_dosing.csv")); cat("\nChange from before dosing to 2010 on:\n"); print(as.data.frame(bt |> mutate(across(where(is.numeric), \(x) round(x, 3)))), row.names = FALSE)
pt$lab <- factor(vlab[as.character(pt$variable)], vlab)
ggsave(file.path(out, "ohau_by_period.png"), ggplot(pp |> mutate(lab = factor(vlab[as.character(variable)], vlab)), aes(period, value, fill = period)) + geom_boxplot(outlier.size = 0.4, linewidth = 0.3, alpha = 0.6) + facet_wrap(~lab, ncol = 2, scales = "free_y") + scale_fill_brewer(palette = "Blues") + labs(x = NULL, y = NULL, fill = NULL, subtitle = "Distributions by dosing period (TN from 2009 only).") + theme_minimal(base_size = 9) + theme(legend.position = "bottom", axis.text.x = element_blank(), plot.subtitle = element_text(size = 8)), width = 10, height = 9, dpi = 130, bg = "white")
# ---- ratios (same-day samples) ----
w <- o |> select(Date, yr, mo, variable, value) |> mutate(variable = as.character(variable)) |> group_by(Date, yr, mo, variable) |> summarise(value = mean(value), .groups = "drop") |> pivot_wider(names_from = variable, values_from = value) |> rename(NH4 = `NH4-N`)
w <- w |> mutate(DIN = pmax(NH4, 0) + pmax(NNN, 0), TNTP = TN / TP, DRP_TP = DRP / TP, DIN_TN = DIN / TN)
w$DINDRP <- (w$DIN / 14.007) / (pmax(w$DRP, 0.0005) / 30.974)   # molar DIN:DRP (DRP floored at 0.0005 g/m3)
rt <- w |> filter(yr >= 2009) |> summarise(across(c(TNTP, DRP_TP, DIN_TN, DINDRP), list(median = \(x) median(x, na.rm = TRUE), q25 = \(x) quantile(x, .25, na.rm = TRUE), q75 = \(x) quantile(x, .75, na.rm = TRUE)))); print(as.data.frame(rt |> mutate(across(everything(), \(x) round(x, 3)))), row.names = FALSE); write_csv(rt |> mutate(across(everything(), \(x) signif(x, 3))), file.path(dat, "ohau_ratios.csv"))
rl <- w |> filter(yr >= 2009) |> select(Date, mo, TNTP, DRP_TP, DIN_TN, DINDRP) |> pivot_longer(-c(Date, mo), names_to = "r", values_to = "v") |> mutate(r = recode(r, TNTP = "TN:TP (mass)", DRP_TP = "DRP / TP", DIN_TN = "DIN / TN", DINDRP = "DIN:DRP (molar)"))
ggsave(file.path(out, "ohau_ratios.png"), ggplot(rl, aes(Date, v)) + geom_point(size = 0.8, alpha = 0.6, colour = "steelblue4") + geom_smooth(method = "loess", span = 0.4, se = FALSE, colour = "black", linewidth = 0.5) + facet_wrap(~r, ncol = 2, scales = "free_y") + labs(x = NULL, y = NULL, subtitle = "Same-day samples, 2009 onwards (TN is not routinely measured before 2009).") + theme_minimal(base_size = 9) + theme(plot.subtitle = element_text(size = 8)), width = 10, height = 6, dpi = 130, bg = "white")
# ---- lake against outlet ----
cd <- targets::tar_read(chem_data) |> mutate(Date = as.Date(Date)) |> filter(DepthFrom <= 5 | is.na(DepthFrom))
lk <- cd |> mutate(ym = floor_date(Date, "month")) |> group_by(ym) |> summarise(TP = mean(`TP (mg/m^3)`, na.rm = TRUE) / 1000, TN = mean(`TN (mg/m^3)`, na.rm = TRUE) / 1000, DRP = mean(`DRP (mg/m^3)`, na.rm = TRUE) / 1000, `NH4-N` = mean(`NH4-N (mg/m^3)`, na.rm = TRUE) / 1000, NNN = mean(`NNN (mg/m^3)`, na.rm = TRUE) / 1000, .groups = "drop") |> pivot_longer(-ym, names_to = "variable", values_to = "lake") |> filter(is.finite(lake))
om <- o |> group_by(ym, variable) |> summarise(outlet = mean(value), .groups = "drop") |> mutate(variable = as.character(variable)); lo <- inner_join(om, lk, by = c("ym", "variable")) |> mutate(variable = factor(variable, vorder)); lo$lab <- factor(vlab[as.character(lo$variable)], vlab)
ls <- lo |> group_by(variable) |> summarise(n = n(), outlet_median = median(outlet), lake_median = median(lake), ratio_of_medians = median(outlet) / median(lake), r = cor(outlet, lake), r_spearman = cor(outlet, lake, method = "spearman"), .groups = "drop"); write_csv(ls |> mutate(across(where(is.numeric), \(x) signif(x, 3))), file.path(dat, "ohau_vs_lake.csv")); cat("\nOutlet against lake (same month):\n"); print(as.data.frame(ls |> mutate(across(where(is.numeric), \(x) round(x, 3)))), row.names = FALSE)
ggsave(file.path(out, "ohau_vs_lake.png"), ggplot(lo, aes(lake, outlet)) + geom_abline(colour = "grey50") + geom_point(aes(colour = ym >= "2011-01-01"), size = 0.9, alpha = 0.6) + facet_wrap(~lab, scales = "free", ncol = 3) + scale_colour_manual(values = c(`FALSE` = "grey50", `TRUE` = "steelblue4"), labels = c(`FALSE` = "to 2010", `TRUE` = "2011 on"), name = NULL) + labs(x = "Lake, sites 2 and 5, top 5 m (monthly mean)", y = "Ohau Channel outlet (monthly mean)", subtitle = "Grey line: 1:1.") + theme_minimal(base_size = 9) + theme(legend.position = "bottom", plot.subtitle = element_text(size = 8)), width = 10, height = 7, dpi = 130, bg = "white")
# ---- model against the outlet ----
rdm <- function(tag, run) { f <- list.files(file.path("calibration/historical", paste0("out_", tag)), "^member_.*[.]rds$", full.names = TRUE)
  bind_rows(lapply(f, \(x) { m <- readRDS(x); m$daily |> filter(Date >= "2005-07-01") |> transmute(member = m$member, Date, TP = TOT_tp_surf * MP + DOPR, TN = TOT_tn_surf * MN + DONR, DRP = PHS_frp_surf * MP, `NH4-N` = NIT_amm_surf * MN, NNN = NIT_nit_surf * MN, TSS = TOT_tss_surf, `Water Temp` = temp_surf) })) |> mutate(run = run) }
M <- bind_rows(rdm(TAG, "With observed alum"), rdm(paste0(TAG, "_noalum"), "No alum")) |> pivot_longer(-c(member, Date, run), names_to = "variable", values_to = "sim")
oo <- o |> filter(Date >= "2005-07-01", Date <= "2022-06-29") |> mutate(variable = as.character(variable)) |> select(Date, variable, obs = value)
J <- inner_join(M, oo, by = c("Date", "variable")) |> mutate(period = as.vector(ifelse(Date < "2011-01-01", "2005 to 2010", "2011 to 2022")))
ens <- J |> group_by(run, variable, Date, period) |> summarise(sim = median(sim), obs = first(obs), .groups = "drop")
st <- ens |> filter(!(variable == "TN" & Date < "2009-01-01")) |> group_by(run, variable, period) |> summarise(n = n(), obs_median = median(obs), sim_median = median(sim), bias_pct = 100 * (mean(sim) / mean(obs) - 1), r = if (n() > 3) cor(sim, obs) else NA_real_, rmse = sqrt(mean((sim - obs)^2)), .groups = "drop"); write_csv(st |> mutate(across(where(is.numeric), \(x) signif(x, 3))), file.path(dat, "ohau_vs_model.csv")); cat("\nModel (ensemble median, surface) against the outlet:\n"); print(as.data.frame(st |> mutate(across(where(is.numeric), \(x) round(x, 3)))), row.names = FALSE)
# monthly series: model envelope and observed outlet points
mm <- M |> mutate(ym = floor_date(Date, "month")) |> group_by(run, variable, member, ym) |> summarise(sim = mean(sim), .groups = "drop") |> group_by(run, variable, ym) |> summarise(lo = min(sim), q1 = quantile(sim, .25), med = median(sim), q3 = quantile(sim, .75), hi = max(sim), .groups = "drop")
mo <- o |> filter(Date >= "2005-07-01", Date <= "2022-06-29") |> mutate(variable = as.character(variable)) |> group_by(ym, variable) |> summarise(obs = mean(value), .groups = "drop")
mm$lab <- factor(vlab[mm$variable], vlab); mo$lab <- factor(vlab[mo$variable], vlab); mm <- mm |> filter(!is.na(lab)); mo <- mo |> filter(!is.na(lab))
CO <- c("With observed alum" = "steelblue4", "No alum" = "firebrick"); FI <- c("With observed alum" = "steelblue", "No alum" = "firebrick")
ggsave(file.path(out, "ohau_vs_model.png"), ggplot(mm, aes(ym)) + geom_vline(xintercept = c(D0, D1), linetype = 2, colour = "grey50") + geom_ribbon(aes(ymin = lo, ymax = hi, fill = run), alpha = 0.15) + geom_ribbon(aes(ymin = q1, ymax = q3, fill = run), alpha = 0.3) + geom_line(aes(y = med, colour = run), linewidth = 0.35) + geom_point(data = mo, aes(ym, obs), size = 0.7, inherit.aes = FALSE) +
  facet_wrap(~lab, ncol = 1, scales = "free_y") + scale_colour_manual(values = CO) + scale_fill_manual(values = FI) + labs(x = NULL, y = NULL, colour = NULL, fill = NULL, subtitle = "Model surface layer (top 5 m, monthly mean; median, interquartile and full range of 50 members) against the monthly outlet samples (points).") + theme_minimal(base_size = 10) + theme(legend.position = "bottom", plot.subtitle = element_text(size = 8)), width = 10, height = 14, dpi = 130, bg = "white")
cat("done\n")
